"""Evaluate layered configuration requests under a supplied policy."""

import re

_INTEGER_ENVIRONMENT_VALUE = re.compile(r"-?[0-9]+\Z")


def _failure(error):
    return {"ok": False, "config": {}, "error": error}


def evaluate(request, policy):
    defaults = policy["defaults"]
    expected_types = policy["types"]
    known_keys = set(defaults)
    config = dict(defaults)

    for layer in request.get("layers", []):
        if any(key not in known_keys for key in layer):
            return _failure("unknown_key")
        for key, value in layer.items():
            if value is None and policy.get("null_resets") is True:
                config[key] = defaults[key]
            else:
                config[key] = value

    environment = request.get("environment", {})
    if environment:
        if policy.get("environment") is not True:
            return _failure("environment")
        if any(key not in known_keys for key in environment):
            return _failure("unknown_key")
        for key, value in environment.items():
            expected = expected_types.get(key)
            if expected == "boolean":
                if value == "true":
                    config[key] = True
                elif value == "false":
                    config[key] = False
                else:
                    return _failure("environment")
            elif expected == "integer":
                if not isinstance(value, str) or not _INTEGER_ENVIRONMENT_VALUE.fullmatch(value):
                    return _failure("environment")
                config[key] = int(value)
            elif expected == "string":
                config[key] = value
            else:
                return _failure("environment")

    validators = {
        "boolean": lambda value: type(value) is bool,
        "integer": lambda value: type(value) is int,
        "string": lambda value: type(value) is str,
    }
    for key, value in config.items():
        validator = validators.get(expected_types.get(key))
        if validator is None or not validator(value):
            return _failure("type")

    return {"ok": True, "config": config, "error": None}
